inline bool inRanges(const IdRange* b, const IdRange* e, int id) {
    const IdRange* it = std::upper_bound(b, e, id, [](int v, const IdRange& r) { return v < r.lo; });
    return it != b && id <= (it - 1)->hi;
}

inline bool isDecoration(int id) { return inRanges(std::begin(kDecoration), std::end(kDecoration), id); }
inline bool isTrigger(int id) { return inRanges(std::begin(kTrigger), std::end(kTrigger), id); }

